export function normalizeSku(sku) {
	if (typeof sku !== "string") throw new TypeError("sku must be a string");
	const clean = sku.trim().toUpperCase();
	if (clean === "") throw new TypeError("sku must not be empty");
	return clean;
}

export function checkQuantity(qty) {
	if (!Number.isInteger(qty) || qty <= 0) throw new RangeError("quantity must be a positive integer");
	return qty;
}

import { checkQuantity, normalizeSku } from "./sku.js";

export class Inventory {
	#items = new Map();

	#entry(sku) {
		return this.#items.get(sku);
	}

	add(sku, qty) {
		const key = normalizeSku(sku);
		checkQuantity(qty);
		const entry = this.#entry(key) ?? { onHand: 0, reserved: 0 };
		entry.onHand += qty;
		this.#items.set(key, entry);
	}

	reserve(sku, qty) {
		const key = normalizeSku(sku);
		checkQuantity(qty);
		const entry = this.#entry(key);
		if (entry === undefined) throw new RangeError(`unknown sku ${key}`);
		if (qty > entry.onHand - entry.reserved) throw new RangeError(`not enough ${key} available`);
		entry.reserved += qty;
	}

	release(sku, qty) {
		checkQuantity(qty);
		const entry = this.#entry(sku);
		if (entry === undefined || qty > entry.reserved) throw new RangeError(`cannot release ${qty}`);
		entry.reserved -= qty;
	}

	remove(sku, qty) {
		const key = normalizeSku(sku);
		checkQuantity(qty);
		const entry = this.#entry(key);
		if (entry === undefined || qty > entry.onHand) throw new RangeError(`cannot remove ${qty}`);
		entry.onHand -= qty;
	}

	snapshot() {
		return [...this.#items]
			.filter(([, e]) => e.onHand > 0 || e.reserved > 0)
			.map(([sku, e]) => ({ sku, onHand: e.onHand, reserved: e.reserved, available: e.onHand - e.reserved }))
			.sort((a, b) => a.sku.localeCompare(b.sku));
	}
}

import assert from "node:assert/strict";
import { test } from "node:test";
import { Inventory } from "../src/inventory.js";

test("add and snapshot", () => {
	const inv = new Inventory();
	inv.add("ab-1", 5);
	inv.add(" AB-1 ", 2);
	assert.deepEqual(inv.snapshot(), [{ sku: "AB-1", onHand: 7, reserved: 0, available: 7 }]);
});

test("reserve and release", () => {
	const inv = new Inventory();
	inv.add("X", 10);
	inv.reserve("X", 4);
	assert.throws(() => inv.reserve("X", 7), RangeError);
	inv.release("X", 1);
	assert.deepEqual(inv.snapshot(), [{ sku: "X", onHand: 10, reserved: 3, available: 7 }]);
});

test("remove", () => {
	const inv = new Inventory();
	inv.add("X", 3);
	inv.remove("X", 3);
	assert.deepEqual(inv.snapshot(), []);
});

